        AssertOperationsEqualReferenced(2, qs => ControlledOnInt(0, X)([qs[0]], qs[1]), TwoQubitGate4_Reference);
        AssertOperationsEqualReferenced(2, TwoQubitGate4, TwoQubitGate4_Reference);
